public static void prefetchCanvas(QuestScreen screen) {
    ApngTextureManager.ensureScreen(screen);
    HashSet<ResourceLocation> textures = new HashSet<ResourceLocation>();
    ApngTextureManager.collectPanelTextures((Panel)screen.questPanel, textures);
    ApngTextureManager.collectChapterThemeTextures(ApngTextureManager.getSelectedChapter(screen), textures);
    ApngTextureManager.replaceScope(ApngScope.QUEST_SCREEN_CANVAS, textures);
}

public static void updateCanvasPlayback(QuestScreen screen) {
    ApngTextureManager.ensureScreen(screen);
    if (CANVAS_SCOPE_TEXTURES.isEmpty()) {
        ApngTextureManager.prefetchCanvas(screen);
    }
    QuestPanel panel = screen.questPanel;
    int panelX = panel.getX();
    int panelY = panel.getY();
    int panelWidth = panel.getWidth();
    int panelHeight = panel.getHeight();
    int paddingX = (int)Math.round((double)panelWidth * 0.5);
    int paddingY = (int)Math.round((double)panelHeight * 0.5);
    int paddedX = panelX - paddingX;
    int paddedY = panelY - paddingY;
    int paddedWidth = panelWidth + paddingX * 2;
    int paddedHeight = panelHeight + paddingY * 2;
    HashMap<ResourceLocation, PlaybackPriority> priorities = new HashMap<ResourceLocation, PlaybackPriority>();
    ApngTextureManager.collectPanelPriorities((Panel)panel, panelX, panelY, panelWidth, panelHeight, paddedX, paddedY, paddedWidth, paddedHeight, priorities);
    ApngTextureManager.applyCanvasPriorities(priorities);
}

public static void syncDetailsScope(ViewQuestPanel panel) {
    QuestScreen screen = (QuestScreen)panel.getGui();
    ApngTextureManager.ensureScreen(screen);
    if (panel.getViewedQuest() == null) {
        ApngTextureManager.closeDetailsScope();
        return;
    }
    HashSet<ResourceLocation> textures = new HashSet<ResourceLocation>();
    ApngTextureManager.collectIcon(panel.getViewedQuest().getIcon(), textures);
    ApngTextureManager.collectPanelTextures((Panel)panel, textures);
    ApngTextureManager.replaceScope(ApngScope.QUEST_DETAILS_PANEL, textures);
}

public static void closeDetailsScope() {
    ApngTextureManager.replaceScope(ApngScope.QUEST_DETAILS_PANEL, Set.of());
}

