@Mod(value="certain_questing_additions")
public final class CertainQuestingAdditionsForge {
    public CertainQuestingAdditionsForge() {
        IEventBus modBus = FMLJavaModLoadingContext.get().getModEventBus();
        EventBuses.registerModEventBus((String)"certain_questing_additions", (IEventBus)modBus);
        CertainQuestingAdditions.init();
        if (FMLEnvironment.dist == Dist.CLIENT) {
            MinecraftForge.EVENT_BUS.addListener(CertainQuestingAdditionsForge::onRegisterCommands);
            modBus.addListener(event -> {
                for (ResourceLocation shaderId : ChapterShaderConfig.discoverShaderIdsForRegistration()) {
                    try {
                        event.registerShader(new ShaderInstance(event.getResourceProvider(), shaderId, DefaultVertexFormat.f_85817_), shader -> ModShaders.register(shaderId, shader));
                    }
                    catch (IOException e) {
                        CertainQuestingAdditions.LOGGER.warn("Failed to register shader {}", (Object)shaderId, (Object)e);
                    }
                }
            });
        }
    }

    private static void onRegisterCommands(RegisterClientCommandsEvent event) {
        event.getDispatcher().register((LiteralArgumentBuilder)LiteralArgumentBuilder.literal((String)"certain-questing-additions").then(LiteralArgumentBuilder.literal((String)"config").executes(stack -> {
            QuestAnimationsConfig.openSettings(null);
            return 1;
        })));
    }
}

